"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { api } from "@/lib/api";

type Step = "npi" | "email" | "phone" | "baa" | "done";

export default function SignupPage() {
  const router = useRouter();
  const [step, setStep] = useState<Step>("npi");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // NPI state
  const [npi, setNpi] = useState("");
  const [providerName, setProviderName] = useState("");
  const [signupId, setSignupId] = useState("");

  // Email state
  const [email, setEmail] = useState("");
  const [emailOtp, setEmailOtp] = useState("");
  const [emailSent, setEmailSent] = useState(false);

  // Phone state
  const [phone, setPhone] = useState("");
  const [phoneOtp, setPhoneOtp] = useState("");
  const [phoneSent, setPhoneSent] = useState(false);

  // BAA state
  const [signerName, setSignerName] = useState("");
  const [signerTitle, setSignerTitle] = useState("");

  const handleVerifyNpi = async () => {
    setError("");
    setLoading(true);
    try {
      const result = await api.verifyNpi(npi);
      if (!result.valid) {
        setError("NPI not found or inactive. Please check the number.");
        return;
      }
      setProviderName(result.provider_name || "");
      setSignupId(result.signup_id || "");
      setStep("email");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Verification failed");
    } finally {
      setLoading(false);
    }
  };

  const handleSendEmailOtp = async () => {
    setError("");
    setLoading(true);
    try {
      await api.sendEmailOtp(signupId, email);
      setEmailSent(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to send code");
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyEmail = async () => {
    setError("");
    setLoading(true);
    try {
      await api.verifyEmail(signupId, email, emailOtp);
      setStep("phone");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Invalid code");
    } finally {
      setLoading(false);
    }
  };

  const handleSendPhoneOtp = async () => {
    setError("");
    setLoading(true);
    try {
      const formattedPhone = phone.startsWith("+1") ? phone : `+1${phone.replace(/\D/g, "")}`;
      await api.sendPhoneOtp(signupId, formattedPhone);
      setPhoneSent(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to send code");
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyPhone = async () => {
    setError("");
    setLoading(true);
    try {
      const formattedPhone = phone.startsWith("+1") ? phone : `+1${phone.replace(/\D/g, "")}`;
      await api.verifyPhone(signupId, formattedPhone, phoneOtp);
      setStep("baa");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Invalid code");
    } finally {
      setLoading(false);
    }
  };

  const handleSignBaa = async () => {
    setError("");
    setLoading(true);
    try {
      await api.signBaa(signupId, signerName, signerTitle, email);
      setStep("done");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to complete signup");
    } finally {
      setLoading(false);
    }
  };

  const steps: { key: Step; label: string }[] = [
    { key: "npi", label: "NPI Verification" },
    { key: "email", label: "Business Email" },
    { key: "phone", label: "Phone" },
    { key: "baa", label: "BAA Agreement" },
  ];

  const currentStepIndex = steps.findIndex((s) => s.key === step);

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center py-12 px-4">
      <div className="max-w-lg w-full">
        <div className="text-center mb-8">
          <h1 className="text-2xl font-bold text-gray-900">Sign up for RunDown</h1>
          <p className="text-gray-600 mt-1">Register your medical practice</p>
        </div>

        {/* Progress Steps */}
        {step !== "done" && (
          <div className="flex items-center justify-center gap-2 mb-8">
            {steps.map((s, i) => (
              <div key={s.key} className="flex items-center gap-2">
                <div
                  className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${
                    i < currentStepIndex
                      ? "bg-green-500 text-white"
                      : i === currentStepIndex
                      ? "bg-brand-600 text-white"
                      : "bg-gray-200 text-gray-500"
                  }`}
                >
                  {i < currentStepIndex ? (
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                  ) : (
                    i + 1
                  )}
                </div>
                {i < steps.length - 1 && (
                  <div className={`w-8 h-0.5 ${i < currentStepIndex ? "bg-green-500" : "bg-gray-200"}`} />
                )}
              </div>
            ))}
          </div>
        )}

        <div className="bg-white rounded-xl shadow-sm border p-6">
          {error && (
            <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm">{error}</div>
          )}

          {/* Step 1: NPI */}
          {step === "npi" && (
            <div className="space-y-4">
              <h2 className="text-lg font-semibold">Verify your NPI</h2>
              <p className="text-sm text-gray-600">
                Enter your 10-digit National Provider Identifier to verify your medical practice.
              </p>
              <input
                value={npi}
                onChange={(e) => setNpi(e.target.value.replace(/\D/g, "").slice(0, 10))}
                placeholder="1234567890"
                maxLength={10}
                className="w-full px-4 py-2.5 border rounded-lg focus:ring-2 focus:ring-brand-500 outline-none font-mono text-lg tracking-wider"
              />
              <button
                onClick={handleVerifyNpi}
                disabled={npi.length !== 10 || loading}
                className="w-full py-2.5 bg-brand-600 text-white rounded-lg font-medium hover:bg-brand-700 disabled:opacity-50"
              >
                {loading ? "Verifying..." : "Verify NPI"}
              </button>
            </div>
          )}

          {/* Step 2: Email */}
          {step === "email" && (
            <div className="space-y-4">
              <h2 className="text-lg font-semibold">Verify business email</h2>
              <p className="text-sm text-gray-600">
                Practice: <strong>{providerName}</strong>
              </p>
              <p className="text-sm text-gray-600">
                Enter your business email. Personal email providers (Gmail, Yahoo, etc.) are not allowed.
              </p>
              <input
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="you@yourpractice.com"
                type="email"
                className="w-full px-4 py-2.5 border rounded-lg focus:ring-2 focus:ring-brand-500 outline-none"
              />
              {!emailSent ? (
                <button
                  onClick={handleSendEmailOtp}
                  disabled={!email || loading}
                  className="w-full py-2.5 bg-brand-600 text-white rounded-lg font-medium hover:bg-brand-700 disabled:opacity-50"
                >
                  {loading ? "Sending..." : "Send verification code"}
                </button>
              ) : (
                <>
                  <input
                    value={emailOtp}
                    onChange={(e) => setEmailOtp(e.target.value.replace(/\D/g, "").slice(0, 6))}
                    placeholder="Enter 6-digit code"
                    maxLength={6}
                    className="w-full px-4 py-2.5 border rounded-lg focus:ring-2 focus:ring-brand-500 outline-none font-mono text-lg tracking-wider text-center"
                  />
                  <button
                    onClick={handleVerifyEmail}
                    disabled={emailOtp.length !== 6 || loading}
                    className="w-full py-2.5 bg-brand-600 text-white rounded-lg font-medium hover:bg-brand-700 disabled:opacity-50"
                  >
                    {loading ? "Verifying..." : "Verify email"}
                  </button>
                </>
              )}
            </div>
          )}

          {/* Step 3: Phone */}
          {step === "phone" && (
            <div className="space-y-4">
              <h2 className="text-lg font-semibold">Verify phone number</h2>
              <p className="text-sm text-gray-600">Enter a US phone number for SMS verification.</p>
              <div className="flex items-center gap-2">
                <span className="text-gray-500 font-medium">+1</span>
                <input
                  value={phone}
                  onChange={(e) => setPhone(e.target.value.replace(/\D/g, "").slice(0, 10))}
                  placeholder="(555) 123-4567"
                  maxLength={10}
                  className="flex-1 px-4 py-2.5 border rounded-lg focus:ring-2 focus:ring-brand-500 outline-none"
                />
              </div>
              {!phoneSent ? (
                <button
                  onClick={handleSendPhoneOtp}
                  disabled={phone.length !== 10 || loading}
                  className="w-full py-2.5 bg-brand-600 text-white rounded-lg font-medium hover:bg-brand-700 disabled:opacity-50"
                >
                  {loading ? "Sending..." : "Send verification code"}
                </button>
              ) : (
                <>
                  <input
                    value={phoneOtp}
                    onChange={(e) => setPhoneOtp(e.target.value.replace(/\D/g, "").slice(0, 6))}
                    placeholder="Enter 6-digit code"
                    maxLength={6}
                    className="w-full px-4 py-2.5 border rounded-lg focus:ring-2 focus:ring-brand-500 outline-none font-mono text-lg tracking-wider text-center"
                  />
                  <button
                    onClick={handleVerifyPhone}
                    disabled={phoneOtp.length !== 6 || loading}
                    className="w-full py-2.5 bg-brand-600 text-white rounded-lg font-medium hover:bg-brand-700 disabled:opacity-50"
                  >
                    {loading ? "Verifying..." : "Verify phone"}
                  </button>
                </>
              )}
            </div>
          )}

          {/* Step 4: BAA */}
          {step === "baa" && (
            <div className="space-y-4">
              <h2 className="text-lg font-semibold">Business Associate Agreement</h2>
              <div className="bg-gray-50 rounded-lg p-4 text-sm text-gray-700 max-h-48 overflow-y-auto border">
                <p className="font-semibold mb-2">HIPAA Business Associate Agreement</p>
                <p className="mb-2">
                  This Business Associate Agreement (&quot;BAA&quot;) is entered into between {providerName} (&quot;Covered
                  Entity&quot;) and RunDown Health, Inc. (&quot;Business Associate&quot;).
                </p>
                <p className="mb-2">
                  Business Associate agrees to: (a) not use or disclose Protected Health Information (PHI) other than
                  as permitted by this Agreement; (b) use appropriate safeguards to prevent unauthorized use or
                  disclosure of PHI; (c) report any unauthorized use or disclosure; (d) ensure subcontractors agree
                  to the same restrictions; (e) make PHI available to individuals as required by HIPAA; (f) make
                  its practices available to HHS for compliance determination.
                </p>
                <p>
                  This agreement is effective upon electronic signature and remains in effect for the duration of
                  the service relationship.
                </p>
              </div>
              <input
                value={signerName}
                onChange={(e) => setSignerName(e.target.value)}
                placeholder="Full name"
                className="w-full px-4 py-2.5 border rounded-lg focus:ring-2 focus:ring-brand-500 outline-none"
              />
              <input
                value={signerTitle}
                onChange={(e) => setSignerTitle(e.target.value)}
                placeholder="Title (e.g., Practice Manager)"
                className="w-full px-4 py-2.5 border rounded-lg focus:ring-2 focus:ring-brand-500 outline-none"
              />
              <button
                onClick={handleSignBaa}
                disabled={!signerName || loading}
                className="w-full py-2.5 bg-brand-600 text-white rounded-lg font-medium hover:bg-brand-700 disabled:opacity-50"
              >
                {loading ? "Completing..." : "I Agree & Complete Registration"}
              </button>
            </div>
          )}

          {/* Done */}
          {step === "done" && (
            <div className="text-center py-4">
              <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <svg className="w-8 h-8 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                </svg>
              </div>
              <h2 className="text-xl font-semibold mb-2">Registration Complete!</h2>
              <p className="text-gray-600 mb-6">
                Your practice <strong>{providerName}</strong> is now registered on RunDown.
              </p>
              <button
                onClick={() => router.push("/login")}
                className="px-6 py-2.5 bg-brand-600 text-white rounded-lg font-medium hover:bg-brand-700"
              >
                Sign in
              </button>
            </div>
          )}
        </div>

        {step !== "done" && (
          <p className="text-center text-sm text-gray-500 mt-4">
            Already registered?{" "}
            <a href="/login" className="text-brand-600 hover:text-brand-700 font-medium">
              Sign in
            </a>
          </p>
        )}
      </div>
    </div>
  );
}

