"use client";

import { useCallback, useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useDropzone } from "react-dropzone";
import { api } from "@/lib/api";
import { formatDate } from "@/lib/utils";

interface Document {
  id: string;
  filename: string;
  status: string;
  page_count: number | null;
  patient_name: string | null;
  created_at: string;
}

interface UserInfo {
  id: string;
  email: string;
  org_name: string;
  role: string;
}

export default function DashboardPage() {
  const router = useRouter();
  const [user, setUser] = useState<UserInfo | null>(null);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState<string>("");

  useEffect(() => {
    api.getMe().then(setUser).catch(() => router.push("/login"));
    api.listDocuments().then(setDocuments).catch(console.error);
  }, [router]);

  const onDrop = useCallback(async (acceptedFiles: File[]) => {
    for (const file of acceptedFiles) {
      if (!file.name.toLowerCase().endsWith(".pdf")) {
        alert("Only PDF files are supported.");
        continue;
      }

      setUploading(true);
      setUploadProgress(`Uploading ${file.name}...`);

      try {
        // Get pre-signed URL
        const { document_id, upload_url } = await api.getPresignedUploadUrl(file.name);

        // Upload directly to S3
        await fetch(upload_url, {
          method: "PUT",
          body: file,
          headers: { "Content-Type": "application/pdf" },
        });

        // Mark upload complete
        await api.markUploadComplete(document_id);

        // Refresh document list
        const docs = await api.listDocuments();
        setDocuments(docs);
        setUploadProgress("");
      } catch (err) {
        console.error("Upload failed:", err);
        setUploadProgress(`Failed to upload ${file.name}`);
      }
    }
    setUploading(false);
  }, []);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: { "application/pdf": [".pdf"] },
    multiple: true,
  });

  const statusBadge = (status: string) => {
    const styles: Record<string, string> = {
      uploading: "bg-yellow-100 text-yellow-800",
      processing: "bg-blue-100 text-blue-800",
      extracting: "bg-purple-100 text-purple-800",
      ready: "bg-green-100 text-green-800",
      error: "bg-red-100 text-red-800",
    };
    return (
      <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${styles[status] || "bg-gray-100 text-gray-800"}`}>
        {status}
      </span>
    );
  };

  if (!user) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-pulse text-gray-500">Loading...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white border-b">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-gray-900">RunDown</h1>
