"use client";

import { useEffect, useState, useRef } from "react";
import { useParams, useRouter } from "next/navigation";
import { api } from "@/lib/api";
import { formatDate, getEventColor } from "@/lib/utils";

interface ExtractedEvent {
  id: string;
  event_type: string;
  event_date: string | null;
  description: string;
  details: Record<string, unknown> | null;
  source_page: number | null;
  confidence: number | null;
}

interface DocumentDetail {
  id: string;
  filename: string;
  status: string;
  page_count: number | null;
  patient_name: string | null;
  created_at: string;
  extracted_events: ExtractedEvent[];
}

interface ChatMessage {
  id: string;
  role: string;
  content: string;
  citations: Array<{ page_number: number; text_snippet: string }> | null;
  created_at: string;
}

const EVENT_TYPES = ["all", "diagnosis", "medication", "procedure", "lab", "visit", "imaging"];

export default function DocumentPage() {
  const params = useParams();
  const router = useRouter();
  const documentId = params.id as string;

  const [doc, setDoc] = useState<DocumentDetail | null>(null);
  const [activeFilter, setActiveFilter] = useState("all");
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [chatInput, setChatInput] = useState("");
  const [chatSessionId, setChatSessionId] = useState<string | null>(null);
  const [chatLoading, setChatLoading] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    api.getDocument(documentId).then(setDoc).catch(() => router.push("/dashboard"));
    api.getChatHistory(documentId).then((history) => {
      if (history.session_id) {
        setChatSessionId(history.session_id);
        setChatMessages(history.messages);
      }
    }).catch(console.error);
  }, [documentId, router]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [chatMessages]);

  const filteredEvents = doc?.extracted_events.filter(
    (e) => activeFilter === "all" || e.event_type === activeFilter
  ) || [];

  const handleSendMessage = async () => {
    if (!chatInput.trim() || chatLoading) return;

    const userMessage: ChatMessage = {
      id: `temp-${Date.now()}`,
      role: "user",
      content: chatInput,
      citations: null,
      created_at: new Date().toISOString(),
    };
    setChatMessages((prev) => [...prev, userMessage]);
    setChatInput("");
    setChatLoading(true);

    try {
      const response = await api.sendChatMessage(documentId, chatInput, chatSessionId || undefined);
      setChatSessionId(response.session_id);
      setChatMessages((prev) => [...prev, response.message]);
    } catch (err) {
      setChatMessages((prev) => [
        ...prev,
        {
          id: `error-${Date.now()}`,
          role: "assistant",
          content: "Sorry, I encountered an error. Please try again.",
          citations: null,
          created_at: new Date().toISOString(),
        },
      ]);
    } finally {
      setChatLoading(false);
    }
  };

  if (!doc) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-pulse text-gray-500">Loading document...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b shrink-0">
        <div className="px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <button onClick={() => router.push("/dashboard")} className="text-gray-500 hover:text-gray-700">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
              </svg>
            </button>
            <div>
              <h1 className="font-semibold text-gray-900">{doc.filename}</h1>
              <p className="text-sm text-gray-500">
                {doc.patient_name && <span className="font-medium">{doc.patient_name}</span>}
                {doc.page_count && <span> &middot; {doc.page_count} pages</span>}
                <span> &middot; {doc.extracted_events.length} events extracted</span>
              </p>
            </div>
          </div>
          <button
            onClick={() => setShowChat(!showChat)}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              showChat ? "bg-brand-600 text-white" : "bg-gray-100 text-gray-700 hover:bg-gray-200"
            }`}
          >
            {showChat ? "Hide Chat" : "Ask Questions"}
          </button>
        </div>
      </header>

      {/* Main Content */}
      <div className="flex-1 flex overflow-hidden">
        {/* Left: PDF Viewer Placeholder */}
        <div className="w-1/2 border-r bg-gray-100 flex items-center justify-center">
          <div className="text-center text-gray-500 p-8">
            <svg className="w-16 h-16 mx-auto mb-4 text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
            <p className="font-medium">PDF Viewer</p>
            <p className="text-sm mt-1">PDF viewer will render here with react-pdf</p>
            <p className="text-sm mt-1">{doc.filename}</p>
          </div>
        </div>

        {/* Right: Timeline + Chat */}
        <div className="w-1/2 flex flex-col overflow-hidden">
          {/* Filter Tabs */}
          <div className="bg-white border-b px-4 py-2 flex gap-1 overflow-x-auto shrink-0">
            {EVENT_TYPES.map((type) => {
              const count = type === "all"
                ? doc.extracted_events.length
                : doc.extracted_events.filter((e) => e.event_type === type).length;
              return (
                <button
                  key={type}
                  onClick={() => setActiveFilter(type)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-medium capitalize whitespace-nowrap transition-colors ${
                    activeFilter === type
                      ? "bg-brand-600 text-white"
                      : "bg-gray-100 text-gray-600 hover:bg-gray-200"
                  }`}
                >
                  {type} ({count})
                </button>
              );
            })}
          </div>

          {/* Timeline */}
          <div className={`flex-1 overflow-y-auto ${showChat ? "max-h-[50%]" : ""}`}>
            <div className="p-4 space-y-3">
              {filteredEvents.length === 0 ? (
                <p className="text-center text-gray-500 py-8">No events found for this filter.</p>
              ) : (
                filteredEvents.map((event) => (
                  <div
                    key={event.id}
                    className={`border rounded-lg p-3 ${getEventColor(event.event_type)}`}
                  >
                    <div className="flex items-start justify-between gap-2">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-xs font-semibold uppercase">{event.event_type}</span>
                          {event.event_date && (
                            <span className="text-xs opacity-75">{formatDate(event.event_date)}</span>
                          )}
                        </div>
                        <p className="text-sm font-medium">{event.description}</p>
                        {event.details && Object.keys(event.details).length > 0 && (
                          <div className="mt-1 text-xs opacity-75">
                            {Object.entries(event.details).map(([key, val]) => (
                              <span key={key} className="mr-3">
                                <strong>{key}:</strong> {String(val)}
                              </span>
                            ))}
                          </div>
                        )}
                      </div>
                      {event.source_page && (
                        <button className="text-xs opacity-60 hover:opacity-100 shrink-0">
                          p.{event.source_page}
                        </button>
                      )}
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>

          {/* Chat Panel */}
          {showChat && (
            <div className="border-t flex flex-col max-h-[50%]">
              <div className="px-4 py-2 bg-gray-50 border-b shrink-0">
                <h3 className="text-sm font-medium text-gray-700">Ask about this document</h3>
              </div>

              {/* Messages */}
              <div className="flex-1 overflow-y-auto p-4 space-y-3">
                {chatMessages.length === 0 && (
                  <p className="text-sm text-gray-500 text-center py-4">
                    Ask a question about this document. For example: &quot;What medications is this patient on?&quot;
                  </p>
                )}
                {chatMessages.map((msg) => (
                  <div
                    key={msg.id}
                    className={`flex ${msg.role === "user" ? "justify-end" : "justify-start"}`}
                  >
                    <div
                      className={`max-w-[85%] rounded-lg px-3 py-2 text-sm ${
                        msg.role === "user"
                          ? "bg-brand-600 text-white"
                          : "bg-white border text-gray-800"
                      }`}
                    >
                      <p className="whitespace-pre-wrap">{msg.content}</p>
                      {msg.citations && msg.citations.length > 0 && (
                        <div className="mt-2 flex flex-wrap gap-1">
                          {msg.citations.map((c, i) => (
                            <button
                              key={i}
                              className="text-xs bg-gray-100 text-gray-600 px-1.5 py-0.5 rounded hover:bg-gray-200"
                            >
                              Page {c.page_number}
                            </button>
                          ))}
                        </div>
                      )}
                    </div>
                  </div>
                ))}
                {chatLoading && (
                  <div className="flex justify-start">
                    <div className="bg-white border rounded-lg px-3 py-2">
                      <div className="flex gap-1">
                        <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" />
                        <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce [animation-delay:0.1s]" />
                        <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce [animation-delay:0.2s]" />
                      </div>
                    </div>
                  </div>
                )}
                <div ref={chatEndRef} />
              </div>

              {/* Input */}
              <div className="p-3 border-t bg-white shrink-0">
                <form
                  onSubmit={(e) => {
                    e.preventDefault();
                    handleSendMessage();
                  }}
                  className="flex gap-2"
                >
                  <input
                    value={chatInput}
                    onChange={(e) => setChatInput(e.target.value)}
                    placeholder="Ask about this document..."
                    className="flex-1 px-3 py-2 border rounded-lg text-sm focus:ring-2 focus:ring-brand-500 focus:border-brand-500 outline-none"
                  />
                  <button
                    type="submit"
                    disabled={chatLoading || !chatInput.trim()}
                    className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    Send
                  </button>
                </form>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

