const API_BASE = "/api";

class ApiClient {
  private token: string | null = null;

  setToken(token: string | null) {
    this.token = token;
    if (token) {
      localStorage.setItem("rundown_token", token);
    } else {
      localStorage.removeItem("rundown_token");
    }
  }

  getToken(): string | null {
    if (this.token) return this.token;
    if (typeof window !== "undefined") {
      this.token = localStorage.getItem("rundown_token");
    }
    return this.token;
  }

  private async request<T>(
    path: string,
    options: RequestInit = {}
  ): Promise<T> {
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      ...(options.headers as Record<string, string>),
    };

    const token = this.getToken();
    if (token) {
      headers["Authorization"] = `Bearer ${token}`;
    }

    const response = await fetch(`${API_BASE}${path}`, {
      ...options,
      headers,
    });

    if (!response.ok) {
      const error = await response.json().catch(() => ({ detail: "Request failed" }));
      throw new Error(error.detail || `HTTP ${response.status}`);
    }

    return response.json();
  }

  // Signup
  async verifyNpi(npiNumber: string) {
    return this.request<{
      valid: boolean;
      npi_number: string;
      provider_name: string | null;
      provider_type: string | null;
      taxonomy: string | null;
      address: Record<string, string> | null;
      signup_id: string | null;
    }>("/signup/verify-npi", {
      method: "POST",
      body: JSON.stringify({ npi_number: npiNumber }),
    });
  }

  async sendEmailOtp(signupId: string, email: string) {
    return this.request("/signup/send-email-otp", {
      method: "POST",
      body: JSON.stringify({ signup_id: signupId, email }),
    });
  }

  async verifyEmail(signupId: string, email: string, otp: string) {
    return this.request("/signup/verify-email", {
      method: "POST",
      body: JSON.stringify({ signup_id: signupId, email, otp }),
    });
  }

  async sendPhoneOtp(signupId: string, phone: string) {
    return this.request("/signup/send-phone-otp", {
      method: "POST",
      body: JSON.stringify({ signup_id: signupId, phone }),
    });
  }

  async verifyPhone(signupId: string, phone: string, otp: string) {
    return this.request("/signup/verify-phone", {
      method: "POST",
      body: JSON.stringify({ signup_id: signupId, phone, otp }),
    });
  }

  async signBaa(signupId: string, signerName: string, signerTitle: string, signerEmail: string) {
    return this.request("/signup/sign-baa", {
      method: "POST",
      body: JSON.stringify({
        signup_id: signupId,
        signer_name: signerName,
        signer_title: signerTitle,
        signer_email: signerEmail,
        agreed: true,
      }),
    });
  }

  // Auth
  async requestMagicLink(email: string) {
    return this.request<{ message: string }>("/auth/request-link", {
      method: "POST",
      body: JSON.stringify({ email }),
    });
  }

  async verifyMagicLink(token: string) {
    return this.request<{
      access_token: string;
      expires_in: number;
      user_id: string;
      org_id: string;
      role: string;
    }>(`/auth/verify/${token}`);
  }

  async getMe() {
    return this.request<{
      id: string;
      email: string;
      org_id: string;
      org_name: string;
      role: string;
    }>("/auth/me");
  }

  // Documents
  async getPresignedUploadUrl(filename: string) {
    return this.request<{
      document_id: string;
      upload_url: string;
      s3_key: string;
    }>("/documents/presign", {
      method: "POST",
      body: JSON.stringify({ filename, content_type: "application/pdf" }),
    });
  }

  async markUploadComplete(documentId: string) {
    return this.request(`/documents/${documentId}/complete`, {
      method: "POST",
    });
  }

  async listDocuments() {
    return this.request<Array<{
      id: string;
      filename: string;
      status: string;
      source_type: string;
      page_count: number | null;
      patient_id: string | null;
      patient_name: string | null;
      created_at: string;
    }>>("/documents");
  }

  async getDocument(id: string) {
    return this.request<{
      id: string;
      filename: string;
      status: string;
      page_count: number | null;
      patient_id: string | null;
      patient_name: string | null;
      created_at: string;
      extracted_events: Array<{
        id: string;
        event_type: string;
        event_date: string | null;
        description: string;
        details: Record<string, unknown> | null;
        source_page: number | null;
        confidence: number | null;
      }>;
    }>(`/documents/${id}`);
  }

  // Patients
  async listPatients() {
    return this.request<Array<{
      id: string;
      name: string;
      mrn: string | null;
      dob: string | null;
      document_count: number;
      created_at: string;
    }>>("/patients");
  }

  // Chat
  async sendChatMessage(documentId: string, message: string, sessionId?: string) {
    return this.request<{
      session_id: string;
      message: {
        id: string;
        role: string;
        content: string;
        citations: Array<{
          page_number: number;
          text_snippet: string;
        }> | null;
        created_at: string;
      };
    }>(`/chat/${documentId}`, {
      method: "POST",
      body: JSON.stringify({ message, session_id: sessionId }),
    });
  }

  async getChatHistory(documentId: string) {
    return this.request<{
      session_id: string | null;
      messages: Array<{
        id: string;
        role: string;
        content: string;
        citations: Array<{
          page_number: number;
          text_snippet: string;
        }> | null;
        created_at: string;
      }>;
    }>(`/chat/${documentId}/history`);
  }
}

export const api = new ApiClient();

