import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function formatDate(dateStr: string | null): string {
  if (!dateStr) return "Unknown date";
  return new Date(dateStr).toLocaleDateString("en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
}

export function getEventColor(eventType: string): string {
  const colors: Record<string, string> = {
    diagnosis: "bg-red-100 text-red-800 border-red-200",
    medication: "bg-blue-100 text-blue-800 border-blue-200",
    procedure: "bg-purple-100 text-purple-800 border-purple-200",
    lab: "bg-green-100 text-green-800 border-green-200",
    visit: "bg-yellow-100 text-yellow-800 border-yellow-200",
    imaging: "bg-orange-100 text-orange-800 border-orange-200",
  };
  return colors[eventType] || "bg-gray-100 text-gray-800 border-gray-200";
}

export function getEventIcon(eventType: string): string {
  const icons: Record<string, string> = {
    diagnosis: "Stethoscope",
    medication: "Pill",
    procedure: "Scissors",
    lab: "FlaskConical",
    visit: "Calendar",
    imaging: "ScanLine",
  };
  return icons[eventType] || "FileText";
}

